import json
from typing import Any, Dict

def _roster_map(raw):
    # 权威名册归一：入参可为 [{offer_seq,name,quantity}] / {offers:[...]} / JSON 字符串
    obj = raw
    if isinstance(obj, str):
        try:
            obj = json.loads(obj)
        except Exception:
            obj = None
    if isinstance(obj, dict):
        obj = obj.get('offers')
    if not isinstance(obj, list):
        return {}
    out = {}
    for i, o in enumerate(obj, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        name = str(o.get('name') or '').strip()
        qty = o.get('quantity')
        if name or qty not in (None, ''):
            out[seq] = {'name': name, 'quantity': qty}
    return out

def _merge_roster(offers, raw):
    # 按 offer_seq 把权威名册的 name/quantity 合并进逐品元素（已有非空 name 不覆盖）
    roster = _roster_map(raw)
    if not roster or not isinstance(offers, list):
        return offers
    for i, o in enumerate(offers, start=1):
        if not isinstance(o, dict):
            continue
        seq = str(o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i)
        r = roster.get(seq)
        if not r:
            continue
        if r.get('name') and not str(o.get('name') or '').strip():
            o['name'] = r['name']
        if r.get('quantity') not in (None, '') and o.get('quantity') in (None, ''):
            o['quantity'] = r['quantity']
    return offers

def _parse(text):
    if not isinstance(text, str) or not text.strip():
        return {}
    t = text.strip()
    if ':' in t and not t.startswith('{') and not t.startswith('['):
        t = t.split(':', 1)[1].strip()
    try:
        v = json.loads(t)
        return v if isinstance(v, dict) else {'raw': t}
    except Exception:
        return {'raw': t}


def _req_summary(req, cfg):
    # requirement_summary：优先需求原文；否则从执行方案提取可读摘要（避免 JSON 大对象导致空串）
    req_plan = cfg.get('plan_json')
    if isinstance(req_plan, str):
        try:
            req_plan = json.loads(req_plan)
        except Exception:
            req_plan = None
    raw = req.get('raw') if isinstance(req, dict) else ''
    if isinstance(raw, str) and raw.strip():
        return raw[:500]
    parts = []
    if isinstance(req_plan, dict):
        base = req_plan.get('baseInfo') or {}
        prc = (req_plan.get('optionalInfo') or {}).get('printContent') or {}
        if base.get('prodPrcName'):
            parts.append(str(base['prodPrcName']))
        if prc.get('prcMonthFee'):
            parts.append('月费%s' % prc['prcMonthFee'])
        if prc.get('containResource'):
            parts.append('含%s' % prc['containResource'])
    if parts:
        return '；'.join(parts)[:500]
    return json.dumps(req_plan if isinstance(req_plan, dict) else req, ensure_ascii=False)[:500]

async def main(args):
    p = args.params
    cfg = _parse(p.get('config_result') or '')
    spec = _parse(p.get('spec_result') or '')
    fee = _parse(p.get('fee_result') or '')
    test = _parse(p.get('test_result') or '')
    req = _parse(p.get('requirement_result') or '')
    # 融合成员组合验证标记：plan 含 group/member_offers 时附加（审批看板动态渲染，避免脏占位符）
    plan_grp = cfg.get('plan_json')
    if isinstance(plan_grp, str):
        try:
            plan_grp = json.loads(plan_grp)
        except Exception:
            plan_grp = None
    has_members = bool(isinstance(plan_grp, dict) and (
        (isinstance(plan_grp.get('group'), dict) and plan_grp['group'].get('members'))
        or plan_grp.get('member_offers')))
    fusion_verification = '＋融合成员组合验证' if has_members else ''
    # config 环节：完整落地配置JSON（内含 offer_id 与 plan_json）
    offer_id = str(cfg.get('offer_id') or '')
    offer_name = str(cfg.get('offer_name') or '')
    # spec 环节：V2.5 起存储结构化 envelope（pass/error_list/audit_summary/audit_suggest），
    #   兼容旧版仅存 markdown 的情形（回退 raw 文本启发式判定）
    audit_summary = str(spec.get('audit_suggest') or spec.get('raw') or spec.get('audit_summary') or '')
    if str(spec.get('pass') or '') in ('0', '1'):
        spec_pass = str(spec.get('pass'))
    else:
        spec_pass = '1' if ('通过' in audit_summary and '驳回' not in audit_summary) else '0'
    # fee 环节：V2.5 起存储结构化 envelope（pass/risk_list/compare_list/risk_summary），
    #   兼容旧版仅存 markdown 的情形（回退 raw 文本启发式判定）
    risk_summary = str(fee.get('risk_summary') or fee.get('raw') or '')
    if str(fee.get('pass') or '') in ('0', '1'):
        fee_pass = str(fee.get('pass'))
    else:
        fee_pass = '0' if ('未通过' in risk_summary or '风险' in risk_summary.replace('未发现', '')) else '1'
    # test 环节：存储的是测试报告文本，受理凭证按标记提取
    test_report = str(test.get('raw') or test.get('test_report') or '')
    order_id = ''
    offer_inst_id = ''
    import re
    m = re.search(r'order[Ii]d[=：:]*\s*([A-Za-z0-9\-]+)', test_report)
    if m:
        order_id = m.group(1)
    m = re.search(r'offerInst[Ii]d[=：:]*\s*([A-Za-z0-9\-]+)', test_report)
    if m:
        offer_inst_id = m.group(1)
    test_passed = '1' if ('通过' in test_report and '失败' not in test_report.split('总体结论')[-1]) else '0'
    summary = {
        'offer_id': offer_id,
        'offer_name': offer_name,
        'fusion_verification': fusion_verification,
        'requirement_summary': _req_summary(req, cfg),
        'config': {'offer_id': offer_id,
                   'plan_json': cfg.get('plan_json')},
        'spec': {'pass': spec_pass, 'audit_summary': audit_summary},
        'fee': {'pass': fee_pass, 'risk_summary': risk_summary},
        'test': {'passed': test_passed, 'order_id': order_id,
                 'offer_inst_id': offer_inst_id, 'test_report': test_report},
        'all_pass': spec_pass == '1' and fee_pass == '1' and test_passed == '1',
    }
    # V3.12 多商品：从 config 落地报文的 offers[] 逐品展开审批看板元素
    offers_out = []
    cfg_offers = cfg.get('offers') if isinstance(cfg, dict) else None
    if isinstance(cfg_offers, list) and cfg_offers:
        # V3.14：按权威名册（需求提报 offers，含 name/quantity）合并销售品名称与数量，
        # 保证审批看板/报告销售品文案与需求提报一致（名册缺失时零变化）。
        _roster = p.get('roster') or p.get('roster_name') or (req.get('offers') if isinstance(req, dict) else '')
        cfg_offers = _merge_roster([dict(c) for c in cfg_offers if isinstance(c, dict)], _roster)
        for i, c in enumerate(cfg_offers, start=1):
            if not isinstance(c, dict):
                continue
            o_id = str(c.get('offer_id') or c.get('offerId') or '')
            offers_out.append({
                'offer_seq': int(c.get('offer_seq') or i),
                'offer_id': o_id,
                'offer_name': str(c.get('offer_name') or c.get('name') or ''),
                'name': str(c.get('name') or c.get('offer_name') or ''),
                'quantity': c.get('quantity'),
                'config_status': str(c.get('status') or ''),
                'plan_json': c.get('plan_json'),
                'spec': dict(summary['spec']),
                'fee': dict(summary['fee']),
                'test': dict(summary['test']),
                'all_pass': summary['all_pass'],
            })
    summary['offers'] = offers_out
    ret: Output = {
        "summary_json": json.dumps(summary, ensure_ascii=False),
        "offer_id": offer_id,
        "all_pass": '1' if summary['all_pass'] else '0',
        "fusion_verification": fusion_verification,
        "offers": json.dumps(offers_out, ensure_ascii=False)
    }
    return ret

import json

MATRIX_HEADER = ['| 序号 | 审批节点 | 审批角色 | 状态 | 审批意见 | 更新时间 |',
                 '| :---: | :--- | :--- | :--- | :--- | :--- |']


def _load(raw):
    if isinstance(raw, (list, dict)):
        return raw
    if not isinstance(raw, str) or not raw.strip():
        return []
    try:
        return json.loads(raw)
    except Exception:
        return []


def _first_offer_with_matrix(offers):
    for o in offers:
        if not isinstance(o, dict):
            continue
        m = o.get('approval_matrix') or o.get('approvalMatrix') or o.get('matrix')
        if isinstance(m, list) and m:
            return m
    return []


def _row(seq, node):
    if not isinstance(node, dict):
        node = {}
    cur = (node.get('current_node') or node.get('node_name')
           or node.get('node') or node.get('step') or '-')
    role = (node.get('approver') or node.get('role')
            or node.get('approver_role') or '-')
    st = node.get('status') or node.get('state') or '-'
    op = node.get('opinion') or node.get('comment') or ''
    tm = (node.get('update_time') or node.get('time')
          or node.get('op_time') or '-')
    return '| %s | %s | %s | %s | %s | %s |' % (seq, cur, role, st, op, tm)


def _render_matrix(matrix):
    if not matrix:
        return ''
    lines = list(MATRIX_HEADER)
    for seq, node in enumerate(matrix, start=1):
        lines.append(_row(seq, node))
    return '\n'.join(lines)


async def main(args):
    p = args.params
    offers = _load(p.get('offers'))
    if isinstance(offers, dict):
        offers = [offers]
    if not isinstance(offers, list):
        offers = []
    approval_id = str(p.get('approval_id') or '').strip()
    status = str(p.get('status') or '').strip()
    reason = str(p.get('reason') or '').strip()
    result_code = str(p.get('resultCode') or '').strip()
    approval_type = str(p.get('approval_type') or '').strip() or 'launch'
    matrix_md = _render_matrix(_first_offer_with_matrix(offers))
    if approval_id:
        # 提交成功：展示工单级审批单号 + 真实审批矩阵，审批进度由工作台自动更新
        parts = ['### 上线审批已提交', '', '| 项 | 值 |', '| :--- | :--- |',
                 '| 工单级审批单号 | %s |' % approval_id,
                 '| 整批提交状态 | %s |' % (status or '审批中'),
                 '| 审批类型 | %s |' % approval_type, '']
        if matrix_md:
            parts += ['**审批矩阵**', '', matrix_md, '']
        parts += ['> 审批已提交（不自动上线/不轮询；审批进度由工作台『上线审批矩阵』自动更新，无需回复查询指令）。', '>',
                  '> **建议处理：** 待审批通过后销售品自动上架（模拟审批约10秒后自动通过）。']
        approval_section = '\n'.join(parts)
    else:
        # 提交被拒/门禁未通过：如实展示原因，不伪造审批单号与审批矩阵
        block_reason = reason or ('提交结果码 %s' % result_code if result_code else '后端未返回审批单，提交未生效')
        parts = ['### 上线审批未提交', '', '| 项 | 值 |', '| :--- | :--- |',
                 '| 整批提交状态 | %s |' % (status or 'FAIL'),
                 '| 审批类型 | %s |' % approval_type,
                 '| 未提交原因 | %s |' % block_reason, '']
        parts += ['> 未生成审批单，本次上线审批**未生效**。', '>',
                  '> **建议处理：** 请先补齐上文缺失环节（如规格稽核 spec、自动测试 test 的通过结果），',
                  '再回复【发起上线审批】重新提交。']
        approval_section = '\n'.join(parts)
    ret: Output = {
        'approval_section': approval_section,
        'approval_type': approval_type,
    }
    return ret

from typing import Any, Dict

def _csv(v):
    # offers 入参可能是 JSON 数组字符串或已归一数组，拍平为 offer_id 逗号串
    import json as _json
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return ''
        try:
            v = _json.loads(s)
        except Exception:
            v = s
    if isinstance(v, dict) and isinstance(v.get('offers'), list):
        v = v['offers']
    if not isinstance(v, list):
        return ''
    ids = []
    for o in v:
        oid = str((o or {}).get('offer_id') or '') if isinstance(o, dict) else ''
        if oid:
            ids.append(oid)
    return ','.join(ids)

async def main(args):
    p = args.params
    chat_id = str(p.get('chat_id') or '')
    offer_id = str(p.get('offer_id') or '')
    offer_name = str(p.get('offer_name') or '')
    req_id = str(p.get('req_id') or '')
    offers_csv = _csv(p.get('offers'))
    qs = ('?chatId=' + chat_id + '&req_id=' + req_id + '&stage=04&view=stage')
    if offer_id:
        qs = ('?offer_id=' + offer_id + '&name=' + offer_name + '&chatId=' + chat_id + '&req_id=' + req_id + '&stage=04&view=stage')
